declare(strict_types=1);
namespace Sexogate;
final class InventoryManagement
{
    public function __construct(private Database $db,private Config $config){}
    public function tracking(string $variant,bool $tracked,bool $expiry,Principal $actor):array
    {$actor->require('catalog',true);return $this->db->transaction(function()use($variant,$tracked,$expiry,$actor){(new Inventory($this->db,$this->config))->definition('bundle-definition',true);$v=$this->db->one('SELECT id FROM variants WHERE id=? FOR UPDATE',[$variant]);RuleViolation::ensure($v,'VARIANT_NOT_FOUND','Stok kodu bulunamadı.',404);$balances=$this->db->all('SELECT on_hand,quarantine FROM inventory_balance WHERE variant_id=? ORDER BY warehouse_id FOR UPDATE',[$variant]);foreach($balances as $b)RuleViolation::ensure((int)$b['on_hand']===0&&(int)$b['quarantine']===0,'TRACKING_STOCK_EXISTS','Takip politikasını değiştirmeden stok ve karantina sıfır olmalıdır.');RuleViolation::ensure(!$this->db->one("SELECT id FROM reservations WHERE variant_id=? AND status='active' AND expires_at>CURRENT_TIMESTAMP(3)",[$variant])&&!$this->db->one('SELECT bundle_variant_id FROM bundle_components WHERE bundle_variant_id=?',[$variant]),'TRACKING_RESERVATION_EXISTS','Aktif rezervasyon veya set üst kodunun politikası değiştirilemez.');RuleViolation::ensure($tracked||!$this->db->one('SELECT id FROM inventory_lots WHERE variant_id=? LIMIT 1',[$variant]),'LOT_HISTORY_EXISTS','Lot geçmişi bulunan stok kodunun izlenebilirliği kapatılamaz.');$this->db->execute('UPDATE variants SET lot_tracking=?,expiry_required=? WHERE id=?',[(int)$tracked,(int)($tracked&&$expiry),$variant]);(new Audit($this->db))->record($actor,'tracking','variants',$variant,['tracked'=>$tracked,'expiry'=>$tracked&&$expiry]);return ['id'=>$variant];});}
    public function accept(string $variant,int $quantity,array $input,string $reference,string $receipt,Principal $actor):array
    {
        $actor->require('inventory',true);if(!$this->db->pdo->inTransaction())throw new \LogicException('RECEIPT_TRANSACTION_REQUIRED');$v=$this->db->one('SELECT lot_tracking,expiry_required FROM variants WHERE id=? FOR UPDATE',[$variant]);RuleViolation::ensure($v&&!$this->db->one('SELECT bundle_variant_id FROM bundle_components WHERE bundle_variant_id=?',[$variant]),'PHYSICAL_VARIANT_REQUIRED','Set üst koduna fiziksel kabul yapılamaz.');$b=$this->db->one("SELECT on_hand FROM inventory_balance WHERE variant_id=? AND warehouse_id='main' FOR UPDATE",[$variant]);RuleViolation::ensure($b,'INVENTORY_NOT_FOUND','Ana depo kaydı gerekir.');$quarantine=($input['quarantine']??false)===true;$lot=null;
        if((bool)$v['lot_tracking']){$number=trim($input['lotNumber']??'');$expires=($input['expiresAt']??null)?:null;RuleViolation::ensure(mb_strlen($number)>0&&mb_strlen($number)<=191,'LOT_NUMBER_REQUIRED','Gerçek üretici lotu gerekir.',400);if($expires!==null){$date=\DateTimeImmutable::createFromFormat('!Y-m-d',$expires,new \DateTimeZone('Europe/Istanbul'));RuleViolation::ensure($date&&$date->format('Y-m-d')===$expires,'LOT_DATE_INVALID','Son kullanma tarihini kontrol edin.',400);if($expires<=(new \DateTimeImmutable('now',new \DateTimeZone('Europe/Istanbul')))->format('Y-m-d'))RuleViolation::ensure($quarantine,'EXPIRED_LOT_QUARANTINE_REQUIRED','Süresi dolmuş lot yalnız karantinaya alınabilir.');}RuleViolation::ensure(!(bool)$v['expiry_required']||$expires!==null,'LOT_EXPIRY_REQUIRED','Gerçek son kullanma tarihi gerekir.',400);$existing=$this->db->one('SELECT * FROM inventory_lots WHERE variant_id=? AND lot_number=? FOR UPDATE',[$variant,$number]);if($existing){RuleViolation::ensure($existing['expires_at']===$expires,'LOT_DATE_MISMATCH','Aynı lot farklı tarihle kaydedilemez.');$lot=$existing['id'];$quarantine=$quarantine||(bool)$existing['quarantined']||$existing['recall_reference']!==null;}else{$lot=Database::id();$this->db->execute('INSERT INTO inventory_lots(id,variant_id,lot_number,expires_at,quarantined,source_reference) VALUES(?,?,?,?,?,?)',[$lot,$variant,$number,$expires,(int)$quarantine,$reference]);}$this->db->execute("INSERT INTO inventory_lot_balances(lot_id,warehouse_id) VALUES(?,'main') ON DUPLICATE KEY UPDATE lot_id=lot_id",[$lot]);$this->db->one("SELECT on_hand FROM inventory_lot_balances WHERE lot_id=? AND warehouse_id='main' FOR UPDATE",[$lot]);$column=$quarantine?'quarantine':'on_hand';$this->db->execute("UPDATE inventory_lot_balances SET $column=$column+? WHERE lot_id=? AND warehouse_id='main'",[$quantity,$lot]);}
        else RuleViolation::ensure(empty($input['lotNumber'])&&empty($input['expiresAt']),'LOT_POLICY_REQUIRED','Lot bilgisi için önce izleme politikası tanımlanmalıdır.');
        $column=$quarantine?'quarantine':'on_hand';$this->db->execute("UPDATE inventory_balance SET $column=$column+? WHERE variant_id=? AND warehouse_id='main'",[$quantity,$variant]);$movement=Database::id();$this->db->execute("INSERT INTO inventory_movements(id,variant_id,warehouse_id,type,quantity,quarantine_quantity,reason,reference,actor_id,lot_id) VALUES(?,?,'main','purchase_receipt',?,?,?,?,?,?)",[$movement,$variant,$quarantine?0:$quantity,$quarantine?$quantity:0,$reference,'purchase-receipt:'.$receipt.':'.$variant,$actor->id,$lot]);return ['movementId'=>$movement,'lotId'=>$lot,'quarantined'=>$quarantine];
    }
    public function recall(string $lot,string $reference,string $key,Principal $actor):array
    {$actor->require('inventory',true);RuleViolation::ensure(mb_strlen(trim($reference))>=10&&mb_strlen($reference)<=2000,'RECALL_REFERENCE_REQUIRED','Üretici geri çağırma referansı gerekir.',400);return (new Audit($this->db))->command($actor,$key,['recall',$lot,$reference],function()use($lot,$reference,$actor){(new Inventory($this->db,$this->config))->definition('bundle-definition');$l=$this->db->one('SELECT variant_id FROM inventory_lots WHERE id=?',[$lot]);RuleViolation::ensure($l,'LOT_NOT_FOUND','Lot bulunamadı.',404);$this->db->all('SELECT warehouse_id FROM inventory_balance WHERE variant_id=? ORDER BY warehouse_id FOR UPDATE',[$l['variant_id']]);$row=$this->db->one('SELECT recall_reference FROM inventory_lots WHERE id=? FOR UPDATE',[$lot]);RuleViolation::ensure($row['recall_reference']===null,'LOT_ALREADY_RECALLED','Lot için geri çağırma kaydı zaten var.');$balances=$this->db->all('SELECT warehouse_id,on_hand FROM inventory_lot_balances WHERE lot_id=? ORDER BY warehouse_id FOR UPDATE',[$lot]);foreach($balances as $b){$q=(int)$b['on_hand'];if($q===0)continue;RuleViolation::ensure($this->db->execute('UPDATE inventory_balance SET on_hand=on_hand-?,quarantine=quarantine+? WHERE variant_id=? AND warehouse_id=? AND on_hand>=?',[$q,$q,$l['variant_id'],$b['warehouse_id'],$q])===1,'LOT_BALANCE_CONFLICT','Lot ve toplam stok tutarsız.');$this->db->execute('UPDATE inventory_lot_balances SET on_hand=0,quarantine=quarantine+? WHERE lot_id=? AND warehouse_id=?',[$q,$lot,$b['warehouse_id']]);$this->db->execute('INSERT INTO inventory_movements(variant_id,warehouse_id,type,quantity,quarantine_quantity,reason,reference,actor_id,lot_id) VALUES(?,?,?, ?,?,?,?,?,?)',[$l['variant_id'],$b['warehouse_id'],'recall',-$q,$q,$reference,'recall:'.$lot.':'.$b['warehouse_id'],$actor->id,$lot]);}$this->db->execute('UPDATE inventory_lots SET recall_reference=?,quarantined=true WHERE id=?',[$reference,$lot]);(new Audit($this->db))->record($actor,'recall','inventory_lots',$lot);return ['id'=>$lot,'quarantined'=>true];});}
    public function bundle(string $variant,int $version,array $components,string $reason,Principal $actor):array
    {$actor->require('catalog',true);RuleViolation::ensure(count($components)>0&&count($components)<=100&&mb_strlen(trim($reason))>=5,'BUNDLE_INVALID','Set bileşenleri ve gerekçesini kontrol edin.',400);usort($components,fn($a,$b)=>strcmp($a['variantId']??'',$b['variantId']??''));return $this->db->transaction(function()use($variant,$version,$components,$reason,$actor){$inventory=new Inventory($this->db,$this->config);$inventory->definition('bundle-definition',true);$inventory->definition('fulfillment-definition',true);$v=$this->db->one('SELECT * FROM variants WHERE id=? FOR UPDATE',[$variant]);RuleViolation::ensure($v&&(int)$v['bundle_version']===$version&&$v['fulfillment_mode']==='warehouse'&&!(bool)$v['lot_tracking'],'BUNDLE_VERSION','Set sürümü veya stok politikası uygun değil.');$balances=$this->db->all('SELECT on_hand,quarantine FROM inventory_balance WHERE variant_id=? ORDER BY warehouse_id FOR UPDATE',[$variant]);foreach($balances as $b)RuleViolation::ensure((int)$b['on_hand']===0&&(int)$b['quarantine']===0,'BUNDLE_PHYSICAL_STOCK','Set üst kodunda fiziksel stok/karantina olamaz.');RuleViolation::ensure(!$this->db->one("SELECT id FROM reservations WHERE variant_id=? AND status='active' AND expires_at>CURRENT_TIMESTAMP(3)",[$variant]),'BUNDLE_RESERVED','Aktif set rezervasyonu varken tanım değişmez.');$old=$this->db->all('SELECT component_variant_id variantId,quantity FROM bundle_components WHERE bundle_variant_id=? ORDER BY component_variant_id',[$variant]);if(!$old)RuleViolation::ensure(!$this->db->one('SELECT id FROM inventory_movements WHERE variant_id=? LIMIT 1',[$variant])&&!$this->db->one('SELECT id FROM order_items WHERE variant_id=? LIMIT 1',[$variant])&&!$this->db->one('SELECT bundle_variant_id FROM bundle_components WHERE component_variant_id=?',[$variant]),'BUNDLE_PHYSICAL_HISTORY','Fiziksel geçmişi olan stok kodu set üst koduna çevrilemez.');$seen=[];foreach($components as $c){$id=$c['variantId']??'';$q=$c['quantity']??0;RuleViolation::ensure($id!==$variant&&!isset($seen[$id])&&is_int($q)&&$q>0&&$q<=1000,'BUNDLE_INVALID','Set bileşenleri tekrarlanamaz veya iç içe olamaz.',400);$seen[$id]=true;$part=$this->db->one('SELECT active FROM variants WHERE id=? FOR SHARE',[$id]);RuleViolation::ensure($part&&(bool)$part['active']&&!$this->db->one('SELECT bundle_variant_id FROM bundle_components WHERE bundle_variant_id=?',[$id]),'BUNDLE_COMPONENT_INVALID','Bileşen etkin fiziksel ürün olmalıdır.');}$this->db->execute('DELETE FROM bundle_components WHERE bundle_variant_id=?',[$variant]);foreach($components as $c)$this->db->execute('INSERT INTO bundle_components(bundle_variant_id,component_variant_id,quantity) VALUES(?,?,?)',[$variant,$c['variantId'],$c['quantity']]);$this->db->execute('UPDATE variants SET bundle_version=bundle_version+1 WHERE id=?',[$variant]);$this->db->execute("UPDATE products SET status='review',updated_at=CURRENT_TIMESTAMP(3) WHERE id=?",[$v['product_id']]);$this->db->execute('UPDATE product_eligibility SET approved=false WHERE variant_id=?',[$variant]);$this->db->execute('INSERT INTO bundle_changes(id,variant_id,version,old_components,new_components,reason,actor_id) VALUES(?,?,?,?,?,?,?)',[Database::id(),$variant,$version+1,$this->config->json($old),$this->config->json($components),$reason,$actor->id]);return ['id'=>$variant,'version'=>$version+1];});}
}
